const areas = [
  {id:'auth', title:'Authentication and OTP flows', scope:'Audit src/app/(auth), src/lib/auth, session cookies, signup/reset/2FA flows. Focus on OTP correctness, resend/replay, rate limiting, redirect, state management, session security, recovery and tests.'},
  {id:'data', title:'Prisma schema, migrations, seed and persistence', scope:'Audit prisma/schema.prisma, prisma/migrations, prisma seed, Prisma config and DB runtime. Focus on schema/migration drift, missing constraints/indexes, dangerous seed/reset behavior, runtime query consistency and production migration readiness.'},
  {id:'api', title:'Next.js API routes and tenant authorization', scope:'Audit src/app/api including auth, v1, admin, cron and upload routes, plus shared API/tenant/RBAC helpers. Focus on auth bypass, tenant isolation, validation, CSRF, rate limits, status codes, error handling and input trust.'},
  {id:'commerce', title:'Commerce, billing, payments and order services', scope:'Audit src/lib/services and src/lib/payments plus relevant route/action callers. Focus on transaction boundaries, idempotency, money arithmetic, payment/webhook verification, stock/coupon races, billing states and order transitions.'},
  {id:'storefront', title:'Storefront, proxy routing and public rendering', scope:'Audit src/app/store, src/proxy.ts, src/lib/storefront*, theme rendering and route generation. Focus on host/slug routing, XSS/HTML injection, data leakage, caching/SEO, checkout correctness and unsafe redirects.'},
  {id:'ui', title:'Admin, super-admin and account UI flows', scope:'Audit src/app/admin, src/app/super-admin, src/app/account, onboarding and shared UI components. Focus on server component runtime errors, permission gating, missing-store states, action wiring, broken navigation, accessibility and inconsistent contracts.'},
  {id:'runtime', title:'Configuration, deployment and operational security', scope:'Audit package manifests/scripts, Docker/Compose, Next config, environment validation, logging, storage, cron, GitHub workflows and deployment configs. Focus on startup/build blockers, exposed secrets, insecure defaults, unsafe scripts, production mismatch and actual CI failure logs for current main commit 5296e77.'},
  {id:'tests', title:'Tests, static quality and cross-module regressions', scope:'Audit all checked-in tests, package scripts, ESLint/TypeScript config, CI workflow and test-to-code coverage. Inspect recent failed GitHub Actions runs for commit 5296e77 and identify exact failure evidence if logs are accessible. Cross-check high-risk behaviors for untested regressions.'}
];
const itemSchema = JSON.stringify({type:'object',properties:{area:{type:'string'},confidence:{type:'string'},findings:{type:'array',items:{type:'object',properties:{severity:{type:'string'},file:{type:'string'},line:{type:'string'},title:{type:'string'},evidence:{type:'string'},impact:{type:'string'},recommendation:{type:'string'},source_url:{type:'string'}},required:['severity','file','line','title','evidence','impact','recommendation','source_url']}},checks_performed:{type:'array',items:{type:'string'}},limitations:{type:'array',items:{type:'string'}}},required:['area','confidence','findings','checks_performed','limitations']});
const results = await parallel('Audit ATLaS repository areas', () => areas.map((area) => agent(
  'You are auditing one exact area of a public GitHub repository. Repository: https://github.com/shazzad098/ATLaS . Audit immutable main commit 5296e77bcaef67245b10579fb79b42fed48c3458 (reported current main). Your bounded area: ' + area.title + '. Scope: ' + area.scope + '\n\nUse GitHub public source pages/raw files and/or public GitHub API; inspect the actual code and cite exact file + line(s) and source URL. Verify any suspected defect against relevant callers/tests/schema before reporting. Report only actionable, reproducible bugs/security/runtime/deployment/test issues; do not list style, speculative claims, or issues already fixed on this commit. Separate confirmed from uncertain evidence in wording. For no confirmed issue, return findings: []. Never modify the repository. Return JSON matching the required schema: area (string), confidence (string), findings (array of {severity: Critical|High|Medium|Low, file, line, title, evidence, impact, recommendation, source_url}), checks_performed (string array), limitations (string array). Include at least one good/working pattern in checks_performed if found. Inspect exactly this area, no broad unrelated repository review.',
  {brief:'Audit ' + area.title, schema:itemSchema, sandbox:'isolated', effort_level:'lite'}
)), {schema:itemSchema});
const successful = results.filter(r => r.ok).map(r => r.value);
const failures = results.map((r,i) => r.ok ? null : {area:areas[i].title,code:r.error.code,message:r.error.message}).filter(Boolean);
const reducerSchema = JSON.stringify({type:'object',properties:{overall_assessment:{type:'string'},highest_priority_findings:{type:'array',items:{type:'object',properties:{severity:{type:'string'},area:{type:'string'},file:{type:'string'},line:{type:'string'},title:{type:'string'},evidence:{type:'string'},impact:{type:'string'},recommendation:{type:'string'},source_url:{type:'string'}},required:['severity','area','file','line','title','evidence','impact','recommendation','source_url']}},confirmed_count:{type:'number'},by_severity:{type:'string'},ci_assessment:{type:'string'},coverage_gaps:{type:'array',items:{type:'string'}},positive_patterns:{type:'array',items:{type:'string'}}},required:['overall_assessment','highest_priority_findings','confirmed_count','by_severity','ci_assessment','coverage_gaps','positive_patterns']});
const reduced = await agent('Synthesize these eight area-audit results for the user. Target repository https://github.com/shazzad098/ATLaS at main commit 5296e77bcaef67245b10579fb79b42fed48c3458. Do not browse or invent new findings; deduplicate, preserve exact evidence/source links and distinctions between confirmed vs uncertain. Prioritize actionable issues, count unique confirmed findings by severity, include CI failure status only if supported by input evidence, and state material audit limits. Data: ' + JSON.stringify(successful) + '\nArea failures: ' + JSON.stringify(failures), {brief:'Synthesize repository audit findings',schema:reducerSchema,sandbox:'isolated',effort_level:'standard'});
return {repository:'https://github.com/shazzad098/ATLaS',commit:'5296e77bcaef67245b10579fb79b42fed48c3458',areas:successful,area_failures:failures,synthesis:reduced.ok?reduced.value:null,synthesis_failure:reduced.ok?null:reduced.error};

